                'month': month,
                'payment': round(monthly_payment, 2),
                'principal': round(principal_payment, 2),
                'interest': round(interest_payment, 2),
                'remaining_balance': max(0.0, round(remaining_balance, 2)) # Ensure balance doesn't go negative due to rounding
